    "link": "https://m.thepaper.cn/detail/34022204",
    "pub_date": "2026-09-07 07:16:58",
    "author": "王天僚/新华社",
    "description": "据朝中社7日报道，“姜健”号驱逐舰入列仪式6日在朝鲜元山港举行，朝鲜劳动党总书记、国务委员长金正恩出席入列仪式。 报道说，朝鲜劳动党中央政治局委员、党中央书记赵春龙作了“姜健”号驱逐舰入列准备情况报告，该舰下水后经过多阶段专业评估试验程序，其战斗性能和可信度得到综合验证。该舰正式入列朝鲜人民军海军。 金正恩发表讲话说，“姜健”号驱逐舰不仅是朝鲜经济、国防、科学技术力量的综合体现，更是朝鲜维护自身权益的自尊、意志、顽强精神的结晶。",
    "content": "据朝中社7日报道，“姜健”号驱逐舰入列仪式6日在朝鲜元山港举行，朝鲜劳动党总书记、国务委员长金正恩出席入列仪式。 报道说，朝鲜劳动党中央政治局委员、党中央书记赵春龙作了“姜健”号驱逐舰入列准备情况报告，该舰下水后经过多阶段专业评估试验程序，其战斗性能和可信度得到综合验证。该舰正式入列朝鲜人民军海军。 金正恩发表讲话说，“姜健”号驱逐舰不仅是朝鲜经济、国防、科学技术力量的综合体现，更是朝鲜维护自身权益的自尊、意志、顽强精神的结晶。"
