    "description": "今年适逢现代文学学者、作家、翻译家贾植芳诞辰110周年。9月5日上午，“把人字写端正——贾植芳先生诞辰110周年纪念展”在上海社会科学馆揭幕。 贾植芳（1916-2008），山西襄汾人，作家、翻译家、学者，复旦大学中文系教授，是中国现代文学、比较文学学科的重要奠基人，曾任中国比较文学学会副会长、上海市比较文学研究会首任会长。2018 年入选上海社联首批“上海社科大师”名单。 1979年，贾植芳先生在复旦大学中文系资料室工作。 贾植芳学术…",
    "content": "今年适逢现代文学学者、作家、翻译家贾植芳诞辰110周年。9月5日上午，“把人字写端正——贾植芳先生诞辰110周年纪念展”在上海社会科学馆揭幕。 贾植芳（1916-2008），山西襄汾人，作家、翻译家、学者，复旦大学中文系教授，是中国现代文学、比较文学学科的重要奠基人，曾任中国比较文学学会副会长、上海市比较文学研究会首任会长。2018 年入选上海社联首批“上海社科大师”名单。 1979年，贾植芳先生在复旦大学中文系资料室工作。 贾植芳学术成果累累，但谈起一生成就，他说，“生命的历程，对我说来，也就是我努力塑造自己的生…"
