    "id": "新闻-澎湃新闻-https://m.thepaper.cn/detail/34006439",
    "feed_name": "澎湃新闻",
    "category": "新闻",
    "title": "法学何为｜吕忠梅：为了一部法典",
    "link": "https://m.thepaper.cn/detail/34006439",
    "pub_date": "2026-09-07 07:01:39",
    "author": "澎湃新闻记者 林平",
    "description": "2026年8月15日，《中华人民共和国生态环境法典》（以下简称生态环境法典）正式施行。这是继民法典之后，中国第二部以“法典”命名的法律，也是目前世界上唯一一部以“生态环境”命名的法典。 这一天，距离吕忠梅第一次听到“环境法”三个字，已经过去了44年。法典通过后，她说：“有人说，我们终于等来了一部法典。我想说，我们终于干出来了一部法典。” 1982年，北大法律系大二学生吕忠梅因一次带路，旁听了一场《中华人民共和国环境保护法（试行）》（以下…",
    "content": "2026年8月15日，《中华人民共和国生态环境法典》（以下简称生态环境法典）正式施行。这是继民法典之后，中国第二部以“法典”命名的法律，也是目前世界上唯一一部以“生态环境”命名的法典。 这一天，距离吕忠梅第一次听到“环境法”三个字，已经过去了44年。法典通过后，她说：“有人说，我们终于等来了一部法典。我想说，我们终于干出来了一部法典。” 1982年，北大法律系大二学生吕忠梅因一次带路，旁听了一场《中华人民共和国环境保护法（试行）》（以下简称环境保护法（试行））修改讨论。她第一次追问：法律为什么还要“试行”？ 44年…"
