    "content": "9月6日，记者从财政部获悉，财政部将于近期发行3000亿元特别国债，支持8家中央金融企业补充核心一级资本。同日，工商银行、农业银行等8家中央金融企业分别发布增资计划，共增资3600亿元，用于补充核心一级资本。 根据公告，工商银行、农业银行两家国有大型商业银行拟向财政部、中国烟草总公司及相关子公司发行A股股票，计划募集资金分别不超过1000亿元、1600亿元。其中，财政部分别认购700亿元、1300亿元。财政部还将向中国进出口银行、中国出口信用保险公司两家政策性金融机构分别注资300亿元、100亿元。此外，中国人保拟…"
