    "description": "中新社柏林9月6日电 德国东部萨克森-安哈尔特州(萨安州)6日举行州议会选举。德国电视一台当晚公布的最新预测显示，极右翼德国选择党(选择党)以44.0%的得票率位居第一。这一得票率较2021年的20.8%大幅上升，刷新了该党在德国州议会选举中的得票纪录。",
    "content": "中新社柏林9月6日电 德国东部萨克森-安哈尔特州(萨安州)6日举行州议会选举。德国电视一台当晚公布的最新预测显示，极右翼德国选择党(选择党)以44.0%的得票率位居第一。这一得票率较2021年的20.8%大幅上升，刷新了该党在德国州议会选举中的得票纪录。"
