    "content": "新华社基辅9月6日电（记者李东旭）据乌克兰国家通讯社6日晚报道，乌克兰总统泽连斯基在与美国总统特朗普的特使威特科夫和女婿库什纳会晤后向媒体表示，乌方与美方和欧洲国家代表当天讨论了对乌越冬援助、安全保障等俄乌冲突涉及的议题，会谈“非常具有实质性”。 泽连斯基说，他与威特科夫和库什纳详细讨论了乌克兰越冬面临的挑战以及美欧伙伴对乌提供支持等问题，乌方期待在防空和能源方面获得大量援助。乌美双方讨论了利用美国液化气越冬的可能性。 泽连斯基说，会谈不仅涉及所需的安全保障，还包括旨在确保战后乌克兰重建的经济保障，战后乌方也需要维…"
