    "content": "新华社南昌9月6日电 特写：“孤村”不孤 新华社记者范帆、熊家林、黄浩然 江西遂川县高坪镇明坑村，大山环抱。 5日凌晨，突如其来的泥石流和山体滑坡，撕破了村庄的宁静。交通、电力、通信中断，明坑村一度成为“孤村”。截至目前，灾害已造成明坑村3人遇难、9人失联。 明坑村位于江西上犹县、遂川县与湖南省桂东县三地交界处，距遂川县城约80公里。灾情牵动人心，各方救援力量闻令而动，向险而行。 中国安能第二工程局接令后，80名救援骨干、45台（套）装备紧急驰援。然而，从遂川县城通往高坪镇的道路被多处坍塌阻断，塌方风险极高。 “路…"
