    "content": "新华社福州9月6日电（记者郑良、吴剑锋）第二十六届中国国际投资贸易洽谈会将于9月8日至11日在福建厦门举办。本届投洽会吸引了来自129个国家和地区、30个国际组织的1200多个政府官方机构、工商企业团组报名参会。 在6日下午举行的新闻发布会上，商务部投资促进事务局副局长于广生介绍，大会以“扩大双向投资 共促全球发展”为永久主题，围绕“投资中国”“中国投资”“国际投资”三大板块，设置20万平方米展示面积、规划14个专业展区，策划举办46项主题活动、52场项目路演活动。 于广生介绍，本届投洽会上，双向投资融合更加有力，…"
