    "description": "国家广播电视总局广播影视发展研究中心、中国广播电视社会组织联合会9月6日在京共同主办的研讨会上，三集纪录片《一路向“南”》获得好评。专家认为，作品通过一位外国电影人的视角，对“中国式现代化”进行深度观察，是新时代对外传播的范本。 据介绍，《一路向“南”》以开罗国际电影节主席、埃及著名演员侯赛因·法赫米在北京、苏州、杭州、深圳、广州等地探访并讲述9组中国普通人的故事，展现今日中国在文化发展、科技应用、生态治理、乡村振兴等领域的真实面貌，9…",
    "content": "国家广播电视总局广播影视发展研究中心、中国广播电视社会组织联合会9月6日在京共同主办的研讨会上，三集纪录片《一路向“南”》获得好评。专家认为，作品通过一位外国电影人的视角，对“中国式现代化”进行深度观察，是新时代对外传播的范本。 据介绍，《一路向“南”》以开罗国际电影节主席、埃及著名演员侯赛因·法赫米在北京、苏州、杭州、深圳、广州等地探访并讲述9组中国普通人的故事，展现今日中国在文化发展、科技应用、生态治理、乡村振兴等领域的真实面貌，9月1日播出以来在25个国家和地区获得了传播。 纪录片《一路向“南”》海报（受访者…"
