    "content": "新华社莫斯科9月6日电（记者栾海）俄罗斯外交部发言人扎哈罗娃6日回应日本首相高市早苗要求俄拆除战胜军国主义日本的纪念碑言论时说，这如同要求“不要刮风和太阳停止发光”一样荒谬，不要把无视本国历史的“病”传染给其他国家。 俄远东哈巴罗夫斯克市4日为一座纪念战胜军国主义日本的纪念碑举行揭幕仪式。该纪念碑是俄目前最大的纪念战胜军国主义日本的纪念碑，由俄罗斯军事历史学会与哈巴罗夫斯克边疆区政府合作建成。纪念碑中央是一尊15米高的苏联士兵雕像，代表击败日本关东军主力的苏联红军。士兵手持长枪，旁边一座绘有菊花图案的界碑被砸成两半…"
