    "content": "新华社基辅9月6日电（记者李东旭）据乌克兰国家通讯社6日报道，乌克兰总统泽连斯基率领的谈判团队与美国总统特使威特科夫和美总统特朗普的女婿库什纳率领的代表团在基辅结束了第一阶段会谈。威特科夫在会后表示，此次会谈“令人鼓舞”。 当地时间17时许，双方结束历时3小时左右的第一阶段会谈。据外媒报道，威特科夫在会谈后说，此次会谈“务实、很重要，我们感到非常鼓舞”，他表示期待取得更多进展。 乌克兰国家通讯社发布的照片显示，乌方谈判团队包括总统泽连斯基、人民公仆党议会党团主席阿拉哈米亚、总统办公室主任布达诺夫、对外情报局局长乌梅…"
