    "content": "新华社上海9月6日电 6日，2026年“一带一路”国际攀岩挑战赛在沪完赛。西班牙组合在收官战混合接力赛中夺金。中国队则凭借在男子、女子接力和男子速度个人赛中的三金位居本届赛事奖牌榜之首。 本届赛事为期三天。6日的速度赛混合接力项目中，中国队和西班牙队在决赛中相遇，但中国组合抢跑犯规，西班牙队就此夺冠。 5日进行的速度接力赛中，东道主中国队男、女各派出两支队伍，并双双会师决赛。最终，本次赛事男子速度个人赛冠军零勇志搭档周子羽以10秒10的成绩在男子组中摘金，龙金宝/虞泽轩获银牌；女子决赛中，张梦丽/张少琴以13秒68…"
