    "author": "王君璐,夏子麟,王修楠,吉宁",
    "description": "近年来，来自中国的潮玩IP加速走出国门，频频亮相世界舞台，成为文化服务出海的亮眼符号。 中国潮玩企业深耕原创内容，以年轻化表达传递东方文化内核，精准对接全球年轻消费群体。 在线下端，潮玩产业聚焦游乐园、零售、文旅、展会等多种商业形态，借助服贸会等平台拓展出海新路径。据统计，2025年中国文化产品进出口总额1434亿美元，文化产品和服务出海主体持续壮大、国际影响力不断提升，让世界看到了一个充满活力、锐意创新的中国。 监制：叶前 马宝军 王…",
    "content": "近年来，来自中国的潮玩IP加速走出国门，频频亮相世界舞台，成为文化服务出海的亮眼符号。 中国潮玩企业深耕原创内容，以年轻化表达传递东方文化内核，精准对接全球年轻消费群体。 在线下端，潮玩产业聚焦游乐园、零售、文旅、展会等多种商业形态，借助服贸会等平台拓展出海新路径。据统计，2025年中国文化产品进出口总额1434亿美元，文化产品和服务出海主体持续壮大、国际影响力不断提升，让世界看到了一个充满活力、锐意创新的中国。 监制：叶前 马宝军 王璐 记者：王君璐 夏子麟 王修楠 吉宁 统筹：丁冬霞 赵方圆 编辑：陶霖 新媒体…"
