    "content": "新华社深圳9月6日电 题：潮起前海，声越重洋——亚太媒体高端论坛嘉宾深度对谈侧记 新华社记者印朋、王丰 以“共筑亚太共同体繁荣之路：媒体的共识与行动”为主题的亚太媒体高端论坛，5日在深圳前海国际会议中心举行。论坛期间，组织了多场中外嘉宾深度对谈，来自中国和亚太经济体的企业界、媒体界、思想界代表畅所欲言，从技术共享谈到产业落地，从场景共创谈到理念互鉴。一幕幕鲜活而富有启迪的场景，折射出亚太合作的广阔机遇与光明前景。 对谈伊始，深圳云豹智能创始人萧启阳从西装上衣口袋里掏出一枚指甲盖大小的芯片，展示给对谈嘉宾和现场媒体记…"
