    "content": "新华社柏林9月6日电（记者赵建通）在6日进行的2026年国际篮联女篮世界杯小组赛中，中国队在一度落后10分的情况下将比赛拖入加时，最终以74:70逆转捷克队，取得本届赛事首场胜利。 中国队开局进攻不畅，首节以17:22落后。第二节捷克队一度将优势扩大到两位数，并以41:33领先结束上半场。易边再战，中国队加强防守，逐渐缩小分差，第三节结束时追至48:53。 9月6日，中国队球员韩旭（右二）在比赛中进攻。新华社记者 贺灿铃 摄 末节双方陷入胶着。比赛还剩27秒时，中国队仍以59:64落后。罗欣棫随后命中关键三分，捷克…"
