    "author": "邓瑞璇,杨淑君",
    "description": "新华社深圳9月6日电（记者杨淑君、邓瑞璇）新华社国家高端智库6日发布中英文智库报告《新大众文艺的繁荣发展与世界影响》。报告生动描绘了新大众文艺繁荣发展的态势，深入剖析了新大众文艺兴起的动因，提出新大众文艺发展需把握的辩证关系，阐释了新大众文艺的世界意义。 报告指出，新大众文艺是在互联网、大数据、人工智能等科技革命驱动下，文艺领域涌现出的由大众广泛参与创作、传播和共享的，反映人民心声和时代主题的全新文艺复合生态。新大众文艺蓬勃发展态势下，…",
    "content": "新华社深圳9月6日电（记者杨淑君、邓瑞璇）新华社国家高端智库6日发布中英文智库报告《新大众文艺的繁荣发展与世界影响》。报告生动描绘了新大众文艺繁荣发展的态势，深入剖析了新大众文艺兴起的动因，提出新大众文艺发展需把握的辩证关系，阐释了新大众文艺的世界意义。 报告指出，新大众文艺是在互联网、大数据、人工智能等科技革命驱动下，文艺领域涌现出的由大众广泛参与创作、传播和共享的，反映人民心声和时代主题的全新文艺复合生态。新大众文艺蓬勃发展态势下，多元主体创作热情迸发、内容形式空前丰富、文化活力充分释放，形成新时代中国文化图景…"
