    "content": "新华社北京9月6日电 日本媒体6日报道，两名驻日美军士兵因涉嫌在冲绳县当街推搡和殴打多名当地居民，被警方逮捕。这两名士兵事发时处于醉酒状态，面临暴行罪指控。 据冲绳县警方通报，这两名海军陆战队士兵分别为22岁和29岁，他们涉嫌于4日22时许在冲绳县冲绳市当街推搡并殴打三名男子。受害者当场报警，警方赶到后将两人逮捕。尚不清楚两人是否已认罪。 当地媒体报道，事发当天冲绳市曾举办庆典活动，一度实行交通管制，三名受害者均为庆典活动工作人员。警方初步判断两名美军士兵可能与受害者发生纠纷，正在调查具体情况。 长期以来，驻日美军…"
