    "content": "新华社北京9月6日电 数百名反对移民者5日堵住通往英国多佛港的道路，导致交通堵塞，多佛港一度中断运营。警方介入后道路当天晚些时候疏通，多佛港逐渐恢复运营。 社交媒体上的视频显示，一些黑衣人手挽手堵住道路，高喊“停船”。英国国家高速公路局5日说，当天通往多佛港的所有道路均被堵住，造成了4英里（约合6.4公里）长的交通堵塞。多佛港运营方5日上午说，“由于正在发生的公共秩序事件”，停止所有进出港的交通。警方表示他们正在“与抗议者接触”。 一名旅客告诉英国天空新闻频道，由于多佛港中断运营，她所乘渡轮在法国敦刻尔克港停留了一…"
