    "content": "新华社深圳9月6日电（记者郑天虹）以“巩固文化主体性推进中国式现代化”为主题的第二届习近平文化思想国际学术研讨会6日在广东深圳举行，来自国内有关研究机构、高校以及海外研究习近平文化思想和中华文明的专家学者和嘉宾约130人出席。 这是9月6日拍摄的第二届习近平文化思想国际学术研讨会现场。新华社记者 毛思倩 摄 中央宣传部副部长洪大用在研讨会开幕式致辞中表示，习近平文化思想是新时代中国共产党领导文化建设实践经验的理论总结，是坚持“两个结合”、推进马克思主义文化理论创新的重大成果，为做好新时代新征程宣传思想文化工作、推动…"
