    "content": "中新网合肥9月6日电(记者 任帅 张强 储玮玮) 9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。“时代楷模”、国防科技大学计算机学院研究员王戟感慨道：“如今，我坐着轮椅，继续追逐前沿科技，继续为科技强军努力工作。只要大脑还能思考，我就是科研战场上的战士，只要双手还能敲键盘，我就可以继续冲锋！”王戟感慨道，何其有幸，他能把个人奋斗和国家命运紧紧相连。祖国不会辜负每一个实干者，“同学们，请你们珍惜现在这个伟大的时代。未来你们无论去往何方，请记住四个字‘同频共振…"
