    "title": "2026中国文化旅游产业博览会项目签约115亿元",
    "link": "http://www.news.cn/20260906/29d2b8ee16fb49b19bc285d592f539d1/c.html",
    "pub_date": "2026-09-06 21:48:19",
    "author": "宋瑞",
    "description": "新华社天津9月6日电（记者宋瑞）2026中国文化旅游产业博览会6日落下帷幕，累计达成各类合作意向超300项，项目签约金额达115亿元。 签约项目涵盖资产盘活、场景创新、文旅融合、数字赋能、城市更新、IP打造等领域，将推动沉浸式文旅、智慧文旅、文创孵化、新型消费场景加速落地。 本届博览会突出资源跨界联动，文商旅体展深度融合亮点鲜明，通过打造五大消费市集、举办休闲运动嘉年华，营造沉浸式体验场景，推动多业态协同共生，实现展会流量向消费增量转化…",
