    "pub_date": "2026-09-06 21:25:13",
    "author": "",
    "description": "中新网合肥9月6日电 (记者 任帅 张强 储玮玮) 9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。 2025年度国家最高科学技术奖获得者、中国工程院院士陈立泉说，科学家的一项重要使命，就是要为国家十年、二十年乃至五十年后，布局未来。国家需要什么，我们就做什么。",
    "content": "中新网合肥9月6日电 (记者 任帅 张强 储玮玮) 9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。 2025年度国家最高科学技术奖获得者、中国工程院院士陈立泉说，科学家的一项重要使命，就是要为国家十年、二十年乃至五十年后，布局未来。国家需要什么，我们就做什么。"
