    "pub_date": "2026-09-06 21:22:51",
    "author": "",
    "description": "中新网合肥9月6日电 (记者 任帅 张强 储玮玮)9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。 2025年度国家最高科学技术奖获得者、中国工程院院士陈立泉说，86岁的他如今又有了新的理想：不远的将来，天上的飞行器是电的，海里的船舶是电的，空间站里，宇航员呼出的二氧化碳也能发电……我把它叫做“电动中国”。",
    "content": "中新网合肥9月6日电 (记者 任帅 张强 储玮玮)9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。 2025年度国家最高科学技术奖获得者、中国工程院院士陈立泉说，86岁的他如今又有了新的理想：不远的将来，天上的飞行器是电的，海里的船舶是电的，空间站里，宇航员呼出的二氧化碳也能发电……我把它叫做“电动中国”。"
