    "content": "9月6日，冯彦哲（右）/黄东萍在夺冠后庆祝。新华社记者 孙非 摄 新华社深圳9月6日电 中国羽毛球大师赛6日在深圳落幕。在中国选手参加的三项决赛中，冯彦哲/黄东萍混双摘金，何济霆/任翔宇、鲍骊婧/曹梓涵分获男双、女双银牌。 混双决赛中，冯彦哲/黄东萍以21:19、21:16战胜马来西亚组合许邦荣/赖沛君，收获本赛季第四冠。 上个月在印度新德里举行的世锦赛上，冯彦哲/黄东萍在混双决赛中不敌法国组合吉凯尔/德尔吕，遗憾摘银。两周后，两人在深圳用一块金牌证明了自己的实力。 冯彦哲赛后表示：“从世锦赛转战大师赛，我们身体和…"
