    "content": "9月5日，以“共筑亚太共同体繁荣之路：媒体的共识与行动”为主题的亚太媒体高端论坛在广东深圳开幕。来自40多个国家和地区以及联合国机构、国际组织的400余位代表出席。 让我们加入群聊，看看亚太媒体“朋友圈”的这场盛会都在聊什么。（记者：吴闫、赵望轩、江雪、杜白羽、刘奕彤、侯鸿博；视频：吴闫）"
