    "content": "新华社北京9月6日电 题：8家中央金融企业迎来增资，有何考量 新华社记者申铖、张千千、吴雨 9月6日，中国工商银行等8家中央金融企业分别发布增资计划，将补充核心一级资本。据统计，8家中央金融企业计划共增资3600亿元。 各方十分关注此次中央金融企业增资背后的考虑以及资金来源。就相关问题，记者采访了专家和业内人士。 增资背后，有何考量？ 当前，中央金融企业经营发展总体稳健，资产质量稳定，主要监管指标均处于“健康区间”。业内人士表示，去年，财政部已发行特别国债5000亿元，支持国有大型商业银行补充核心一级资本。和去年类…"
