    "content": "新华社巴黎9月6日电（记者张百慧）继在西班牙马德里演出引发热烈反响后，由中国经典歌剧《原野》5日在法国巴黎普莱耶勒音乐厅完成巴黎首场演出，第二场于当地时间6日晚上演。 5日晚的舞台上，中国民族韵味与西式作曲技法交织相融，咏叹段落情感喷薄，将人性之中的挣扎、不甘以及对自由的向往渐次释放。台下观众沉浸于跌宕起伏的故事之中，当终曲的旋律消散，全体观众向台上艺术家致以持久热烈的掌声。当晚表演吸引近千名观众，中国驻法国大使邓励也到场观看演出。 据中国歌剧舞剧院院长冯俐介绍，《原野》是中国歌剧探索中西艺术融合、较早走向国际舞台…"
