    "author": "陈晨,齐琪",
    "description": "新华社达喀尔9月6日电（记者陈晨 齐琪）努瓦克肖特消息：据毛里塔尼亚媒体6日报道，该国西南部卜拉克纳区马勒市一栋在建建筑5日发生倒塌，造成5人死亡、5人受伤。 报道援引卜拉克纳区民防部门负责人消息说，这栋拟用作加油站的建筑于当地时间5日下午倒塌。事发时建筑内有10名工人，其中5人当场死亡，另有5人被救出。伤者已被送往当地医疗机构救治，部分人员伤势严重。",
