    "content": "新华社北京9月6日电 美国哥伦比亚特区联邦巡回上诉法院4日驳回联邦政府上诉，维持下级法院裁决，阻止联邦政府在11月国会中期选举前利用一个联邦移民数据库核查和取消选民投票资格。 据路透社5日报道，审理该案的三人合议庭中，两名法官支持6月22日由哥伦比亚特区联邦地区法院斯帕克尔·苏克纳南法官作出的一审裁决。这两人由前总统奥巴马任命。对一审裁决持异议的法官则由现任总统特朗普任命。 特朗普3月31日签署一项行政命令，要求各州实施更严格的选举邮寄投票规则，要求国土安全部与社会保障署合作，为每个州创建已确认有资格投票的美国公民…"
