    "description": "新华社北京9月6日电 题：让新大众文艺在数智时代更好绽放光彩 新华社记者杨淑君 9月6日，在广东深圳举行的第二届习近平文化思想国际学术研讨会上，由新华社国家高端智库课题组撰写的《新大众文艺的繁荣发展与世界影响》中英文智库报告面向全球发布。报告系统梳理和深度阐释了这一新时代文艺领域的重要现象，兼具实践观照、理论提炼与全球视野。 新大众文艺是在互联网、大数据、人工智能等科技革命驱动下，文艺领域涌现出的由大众广泛参与创作、传播和共享的，反映人…",
