    "content": "记者今天从西藏自治区吉隆县“8·26”泥石流灾害应急救援指挥部举行的中外媒体见面会上了解到，针对吉隆口岸选址问题，日喀则市委副书记、代理市长罗布次仁表示，吉隆口岸自古便是茶马古道、唐蕃古道的核心节点，承载中尼双方千年贸易与人文交流，吉隆沟有地形、交通、边境通行的便利条件，历史上形成了重要陆路通道。据唐代、清代等相关史料记载，吉隆河谷地区是中国西藏与尼泊尔边民民间往来，双方人员可以通过喜马拉雅山脉来往通行。对口岸功能恢复等事宜进行深入研究论证。"
