    "author": "张千千",
    "description": "新华社北京9月6日电（记者张千千）9月6日，中国再保董事会审议通过并披露向特定对象发行内资股方案。本次发行拟由财政部以现金方式认购，计划募集资金总额30亿元人民币，在扣除相关发行费用后将全部用于增加中国再保核心一级资本，募集资金规模与最终发行方案以相关监管部门最终批复为准。发行价格为1.33元/股，较中国再保近期H股二级市场价格实现溢价发行，拟发行股份约22.56亿股，发行对象承诺长期持有本次认购股份。",
    "content": "新华社北京9月6日电（记者张千千）9月6日，中国再保董事会审议通过并披露向特定对象发行内资股方案。本次发行拟由财政部以现金方式认购，计划募集资金总额30亿元人民币，在扣除相关发行费用后将全部用于增加中国再保核心一级资本，募集资金规模与最终发行方案以相关监管部门最终批复为准。发行价格为1.33元/股，较中国再保近期H股二级市场价格实现溢价发行，拟发行股份约22.56亿股，发行对象承诺长期持有本次认购股份。"
